import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().start();
    }

    void start() {
        InputReader reader = new InputReader(System.in);
        OutputWriter writer = new OutputWriter(System.out);
        Task solver = new Task();
        solver.run(1, reader, writer);
        writer.flush();
    }

    static class Task {
        private static final long MOD = 1000000007L;
        private static final long INF = (long)1e18 + 1;
        private long[][] C = new long[100][100];

        private long multiply(long base, int n1, int r1, int n2, int r2) {
            base = (base * C[n1][r1]) % MOD;
            base = (base * C[n2][r2]) % MOD;
            return base;
        }

        void run(int testNum, InputReader in, OutputWriter out) {
            int N = in.nextInt();
            int capacity = in.nextInt();
            int groupA = 0, groupB = 0;
            for (int i = 0; i < N; i++) {
                int val = in.nextInt();
                if (val == 50) groupA++;
                else groupB++;
            }

            // Build Pascal's triangle
            for (int i = 0; i < 100; i++) {
                C[i][0] = C[i][i] = 1;
                for (int j = 1; j < i; j++) {
                    C[i][j] = (C[i-1][j] + C[i-1][j-1]) % MOD;
                }
            }

            long[][][] minDist = new long[200][200][2];
            long[][][] numWays = new long[200][200][2];
            for (int i = 0; i < 200; i++) {
                for (int j = 0; j < 200; j++) {
                    Arrays.fill(minDist[i][j], INF);
                    Arrays.fill(numWays[i][j], 0);
                }
            }

            minDist[0][0][0] = 0;
            numWays[0][0][0] = 1;

            Deque<State> deque = new ArrayDeque<>();
            deque.add(new State(0, 0, 0, 0));

            while (!deque.isEmpty()) {
                State s = deque.removeFirst();
                int x = s.x;
                int y = s.y;
                int side = s.side;
                long d = minDist[x][y][side];

                if (side == 0) {
                    int remainingA = groupA - x;
                    int remainingB = groupB - y;
                    for (int takeA = 0; takeA <= remainingA; takeA++) {
                        for (int takeB = 0; takeB <= remainingB; takeB++) {
                            if (takeA == 0 && takeB == 0) continue;
                            int weight = takeA * 50 + takeB * 100;
                            if (weight > capacity) break;
                            int nx = x + takeA;
                            int ny = y + takeB;
                            int nextSide = side ^ 1;
                            if (minDist[nx][ny][nextSide] >= d + 1) {
                                if (minDist[nx][ny][nextSide] > d + 1) {
                                    minDist[nx][ny][nextSide] = d + 1;
                                    deque.addLast(new State(nx, ny, nextSide, d + 1));
                                    numWays[nx][ny][nextSide] = (numWays[nx][ny][nextSide] + multiply(numWays[x][y][side], remainingA, takeA, remainingB, takeB)) % MOD;
                                } else {
                                    numWays[nx][ny][nextSide] = (numWays[nx][ny][nextSide] + multiply(numWays[x][y][side], remainingA, takeA, remainingB, takeB)) % MOD;
                                }
                            }
                        }
                    }
                } else {
                    int remainingA = x;
                    int remainingB = y;
                    for (int takeA = 0; takeA <= remainingA; takeA++) {
                        for (int takeB = 0; takeB <= remainingB; takeB++) {
                            if (takeA == 0 && takeB == 0) continue;
                            int weight = takeA * 50 + takeB * 100;
                            if (weight > capacity) break;
                            int nx = x - takeA;
                            int ny = y - takeB;
                            int nextSide = side ^ 1;
                            if (minDist[nx][ny][nextSide] >= d + 1) {
                                if (minDist[nx][ny][nextSide] > d + 1) {
                                    minDist[nx][ny][nextSide] = d + 1;
                                    deque.addLast(new State(nx, ny, nextSide, d + 1));
                                    numWays[nx][ny][nextSide] = (numWays[nx][ny][nextSide] + multiply(numWays[x][y][side], remainingA, takeA, remainingB, takeB)) % MOD;
                                } else {
                                    numWays[nx][ny][nextSide] = (numWays[nx][ny][nextSide] + multiply(numWays[x][y][side], remainingA, takeA, remainingB, takeB)) % MOD;
                                }
                            }
                        }
                    }
                }
            }

            if (minDist[groupA][groupB][1] == INF) {
                out.println(-1);
            } else {
                out.println(minDist[groupA][groupB][1]);
            }
            out.println(numWays[groupA][groupB][1]);
        }

        static class State {
            int x, y, side;
            long dist;
            State(int x, int y, int side, long dist) {
                this.x = x;
                this.y = y;
                this.side = side;
                this.dist = dist;
            }
        }
    }

    static class InputReader {
        private final InputStream input;
        private final byte[] buffer = new byte[1024];
        private int pos = 0, end = 0;

        public InputReader(InputStream stream) {
            input = stream;
        }

        private int read() {
            if (end == -1) throw new RuntimeException();
            if (pos >= end) {
                pos = 0;
                try { end = input.read(buffer); } catch (IOException e) { throw new RuntimeException(); }
                if (end <= 0) return -1;
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int c;
            while ((c = read()) <= ' ') {}
            int num = 0;
            do {
                num = num * 10 + (c - '0');
            } while ((c = read()) > ' ');
            return num;
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream stream) {
            writer = new PrintWriter(stream);
        }

        public void println(long value) {
            writer.println(value);
        }

        public void flush() {
            writer.flush();
        }
    }
}
